args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dc: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  {
    dbr:Supercock (dbo:country|dbp:country) ?c .
    dbr:Intelligence_and_the_Japanese_Civilian (dbo:country|dbp:country) ?c .
  }
  UNION
  {
    dbr:Supercock dc:subject ?cat1 .
    dbr:Intelligence_and_the_Japanese_Civilian dc:subject ?cat2 .
    ?cat1 rdfs:label ?lab1 .
    ?cat2 rdfs:label ?lab2 .
    FILTER (regex(str(?lab1), "American", "i") && regex(str(?lab2), "American", "i"))
  }
}

